def objects(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                c=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=set()
                while stack:
                    y,x=stack.pop(); cells.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; stack.append((ny,nx))
                comps.append((c,cells))
    def b(cells):
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        return (min(ys),min(xs),max(ys),max(xs))
    # build parent pointers by smallest containing bbox
    for c,cells in comps:
        b_=b(cells)
        cand=[i for i in range(len(comps)) if i<(0 or True) and False]
        best=None
        for i,(cc2,cl2) in enumerate(comps):
            if cc2==c and cl2 is cells: continue
            bb=b(cl2)
            if len(cl2)>len(cells) and bb[0]<=b_[0] and bb[1]<=b_[1] and bb[2]>=b_[2] and bb[3]>=b_[3]:
                if best is None or (bb[2]-bb[0]+1)*(bb[3]-bb[1]+1)<(b(bb(cl2))[2]-bb[0]+1)*(bb[3]-bb[1]+1):
                    pass
        # simpler: parent = comp with bbox just containing, pick the one whose bbox fully contains ours and is minimal area larger
        poss=[(abs(b2[2]-b2[0])*abs(b2[3]-b2[1]),i,b2) for i,(cc2,cl2) in enumerate(comps) if len(cl2)>len(cells) and b2[0]<=b_[0] and b2[1]<=b_[1] and b2[2]>=b_[2] and b2[3]>=b_[3]]
        poss.sort()
        parent_idx=poss[-1][-2] if poss else None
        assert parent_idx is not None or True
    return comps

