# Output: reverse the color order along each object's depth (outermost <-> innermost, second-outer <-> ...).
# Objects are separated by background; within each object, components of same color form one ring per depth.
# Build tree: root comps at top (largest bboxes), children = smaller comps whose bbox is inside parent's bbox.

def f(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                c=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=set()
                while stack:
                    y,x=stack.pop(); cells.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; stack.append((ny,nx))
                comps.append({'c':c,'cells':cells})
    def b(cells):
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        return (min(ys),min(xs),max(ys),max(xs)), len(cells)
    roots=[]; kids={}; sizes={}
    for ci,c in enumerate(comps):
        bb,size=b(c['cells'])
        sizes[ci]=size
        cand=[cj for cj,c2 in enumerate(comps) if cj!=ci and size[cj]>size[ci]
              and b(c2['cells'])[0]<=bb[0] and b(c2['cells'])[1]<=bb[1] and b(c2['cells'])[2]>=bb[2] and b(c2['cells'])[3]>=bb[3]]
        par=max(cand,key=lambda cj:b(c2['cells'][0])) if False else max(cand,key=lambda cj:(b(comps[cj]['cells'])[2]-b(comps[cj]['cells'])[0]+1)*(b(comps[cj]['cells'])[3]-b(comps[cj]['cells'])[1]+1)) if cand else None
        if par is None:
            roots.append(ci)
        else:
            kids.setdefault(par,[]).append(ci)
    out=[r[:] for r in g]
    done=set()
    for ri in roots:
        obj=[]
        stack=[ri]
        while stack:
            ci=stack.pop()
            if ci in done: continue
            done.add(ci); obj.append(ci)
            for kj in kids.get(ci,[]): stack.append(kj)
        # rings sorted by depth (distance from outer bbox edge) ascending? use component index ordering: larger first -> deeper last
        order=sorted(obj,key=lambda ci:-sizes[ci])
        rings=[comps[ci]['c'] for ci in order]
        rev=rings[::-1]
        m=dict(zip(rings,rev))
        for ci in obj:
            for p in comps[ci]['cells']:
                out[p[0]][p[1]]=m[comps[ci]['c']]
    return out

