    seen=[[False]*W for _ in range(H)]; Cs=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=set()
                while st:
                    y,x=st.pop(); cells.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; st.append((ny,nx))
                Cs.append({'c':c,'cells':cells})
    def bb(cells):
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        return (min(ys),min(xs),max(ys),max(xs))
    A={}
    for ci,c in enumerate(Cs):
        b=bb(c['cells']); A[ci]=(b[2]-b[0]+1)*(b[3]-b[1]+1)
    roots=[]; kids={}
    for ci,c in enumerate(Cs):
        b=bb(c['cells']); pa=A[ci]
        cand=[cj for cj in range(len(Cs)) if cj!=ci and A[cj]>pa
              and bb(Cs[cj]['cells'])[0]<=b[0] and bb(Cs[cj]['cells'])[1]<=b[1]
              and bb(Cs[cj]['cells'])[2]>=b[2] and bb(Cs[cj]['cells'])[3]>=b[3]]
        par=max(cand,key=lambda cj:A[cj]) if cand else None
        if par is None: roots.append(ci)
        else: kids.setdefault(par,[]).append(ci)
    out=[row[:] for row in g]
    done=set()
    for ri in roots:
        obj=[]; st=[ri]
        while st:
            ci=st.pop()
            if ci in done: continue
            done.add(ci); obj.append(ci)
            st.extend(kids.get(ci,[]))
        order=sorted(obj,key=lambda ci:-A[ci])
        rings=[Cs[ci]['c'] for ci in order]
        rev=rings[::-1]
        m=dict(zip(rings,rev))
        for ci in obj:
            for p in Cs[ci]['cells']:
                out[p[0]][p[1]]=m[Cs[ci]['c']]
    return out
