G=load()
from collections import deque
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=set()
                while q:
                    y,x=q.popleft(); cells.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append({'c':c,'cells':set(cells)})
    return out
def f(g):
    Cs=comps(g)
    items=[]
    for comp in Cs:
        ys=[p[0] for p in comp['cells']]; xs=[p[1] for p in comp['cells']]
        items.append({
            'c':comp['c'],
            'bbox':(min(ys),max(ys),min(xs),max(xs)),
            'area':(max(ys)-min(ys)+1)*(max(xs)-min(xs)+1),
            'cells':comp['cells']
        })
    # cluster: bbox overlaps (containment也算)
    n=len(items); used=[False]*n; clusters=[]
    for i in range(n):
        if used[i]: continue
        stack=[i]; cur=[items[i]]; used[i]=True
        while stack:
            idx=stack.pop()
            b=items[idx]['bbox']; A=b[1]-b[0]+1; B=b[3]-b[2]+1
            for j in range(n):
                if used[j]: continue
                b2=items[j]['bbox']
                if not (A>=b2[1] and A<=b2[3] or True): pass
                # bbox overlap or containment either way
                if (b[0]<=b2[0] and b[1]>=b2[1] and b[2]<=b2[2] and b[3]>=b2[3]) or \
                   (b2[0]<=b[0] and b2[1]>=b[1] and b2[2]<=b[2] and b2[3]>=b[3]):
                    used[j]=True; stack.append(j); cur.append(items[j])
        clusters.append(cur)
    res=[[g[y][x] for x in range(len(g[0]))] for y in range(len(g))]
    for cl in clusters:
        seq=sorted(cl,key=lambda s:s['area'])
        m={seq[i]['c']:seq[-(i+1)]['c'] for i in range(len(seq))}
        for s in cl:
            for p in s['cells']:
                res[p[0]][p[1]]=m[s['c']]
    return res
